DELETE FROM SZD_JSMX

    IMPORT_DATE = #{importDate,jdbcType=DATE}
    and DATA_FILE = #{dataFile,jdbcType=VARCHAR}

        and SZD_JSMX.ZQZH || SZD_JSMX.XWH1 IN (
            SELECT BOND_ID || SH_SEATNO
             FROM STL_VW_BOND_SEAT_PTL_NO

            #{portfolioId,jdbcType=VARCHAR}

        )

